     }

     public void testConfigDefaultPropsToAction() throws Exception {
+        String actionXml = "<map-reduce>"
+                + "        <prepare>"
+                + "          <delete path=\"${nameNode}/user/${wf:user()}/mr/${outputDir}\"/>"
+                + "        </prepare>"
+                + "        <configuration>"
+                + "          <property><name>bb</name><value>BB</value></property>"
